"""Global interaction layer checks. Needs `vite preview --port 4180`."""
import os
os.environ.setdefault('PLAYWRIGHT_BROWSERS_PATH','/opt/pw-browsers')
from playwright.sync_api import sync_playwright
B='http://localhost:4180'
def ok(n,c,x=''): print('PASS' if c else 'FAIL', n, x, flush=True)
def op(pg): pg.keyboard.press('Control+k'); pg.wait_for_timeout(450)
def typ(pg,t): pg.keyboard.type(t); pg.wait_for_timeout(350)
def dlg(pg): return pg.locator('[role=dialog]').count()
def act(pg): return pg.evaluate("(()=>{const e=document.activeElement;return e?(e.id||e.getAttribute('aria-label')||e.tagName):''})()")
def headers(pg): return pg.evaluate("[...document.querySelectorAll('[role=dialog] [role=listbox] li > p')].map(p=>p.textContent.trim())")
def opts(pg): return pg.evaluate("[...document.querySelectorAll('[role=option]')].map(o=>o.textContent)")
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':1280,'height':900}); pg=ctx.new_page(); errs=[]
    pg.on('pageerror',lambda e:errs.append(str(e))); pg.on('console',lambda m: m.type=='error' and '403' not in m.text and 'ERR_NAME_NOT_RESOLVED' not in m.text and errs.append(m.text))
    pg.goto(B); pg.wait_for_timeout(1500)
    # ---------- Ctrl+K reliability + focus
    pg.get_by_label('More pages').focus(); op(pg)
    ok('Ctrl+K opens, input focused', dlg(pg)==1 and pg.evaluate("document.activeElement.getAttribute('role')")=='combobox')
    pg.keyboard.press('Control+k'); pg.wait_for_timeout(500)
    ok('Ctrl+K again closes, focus returns to opener', dlg(pg)==0 and act(pg)=='More pages')
    pg.evaluate("window.dispatchEvent(new KeyboardEvent('keydown',{key:'k',code:'KeyK',ctrlKey:true,repeat:true}))"); pg.wait_for_timeout(300); ok('auto-repeat does not open', dlg(pg)==0)
    op(pg); pg.evaluate("window.dispatchEvent(new KeyboardEvent('keydown',{key:'k',code:'KeyK',ctrlKey:true,repeat:true}))"); pg.wait_for_timeout(300); ok('auto-repeat does not flicker-close', dlg(pg)==1)
    pg.keyboard.press('Escape'); pg.wait_for_timeout(850)
    pg.evaluate("window.dispatchEvent(new KeyboardEvent('keydown',{key:'л',code:'KeyK',ctrlKey:true}))"); pg.wait_for_timeout(450); ok('works on non-Latin layout (physical K)', dlg(pg)==1); pg.keyboard.press('Escape'); pg.wait_for_timeout(850)
    pg.evaluate("window.dispatchEvent(new KeyboardEvent('keydown',{key:'k',code:'KeyK',ctrlKey:true,isComposing:true}))"); pg.wait_for_timeout(300); ok('ignored during IME composition', dlg(pg)==0)
    pg.goto(B+'/contact'); pg.wait_for_timeout(1200); pg.locator('#msg').focus(); pg.keyboard.type('draft'); op(pg)
    ok('Ctrl+K works while typing in a textarea', dlg(pg)==1); pg.keyboard.press('Escape'); pg.wait_for_timeout(850)
    ok('Esc restores focus to the textarea (text kept)', act(pg)=='msg' and pg.locator('#msg').input_value()=='draft')
    # ---------- search grouping / highlight / empty
    pg.goto(B+'/'); pg.wait_for_timeout(1200); op(pg); typ(pg,'project')
    h=headers(pg); ok('result group headers are unique (no interleaving)', len(h)==len(set(h)) and len(h)>=2, str(h))
    ok('matches are highlighted', pg.locator('[role=dialog] mark').count()>=1)
    ok('results carry icons and type chips', pg.locator('[role=option] svg').count()>=3 and 'Completed' in ' '.join(opts(pg)))
    pg.keyboard.press('ArrowDown'); pg.keyboard.press('ArrowDown'); pg.wait_for_timeout(300)
    ok('arrow keys move selection (aria-activedescendant follows)', pg.evaluate("document.activeElement.getAttribute('aria-activedescendant')===[...document.querySelectorAll('[role=option]')][2].id"))
    pg.keyboard.press('Escape'); pg.wait_for_timeout(850)
    op(pg); typ(pg,'zzzzqq'); ok('empty state message + Browse pages fallback', pg.locator('p:not(.sr-only):has-text("No results for")').count()==1 and 'BROWSE PAGES' in ' '.join(headers(pg)).upper() and pg.locator('[role=option]').count()>=11)
    pg.keyboard.press('Enter'); pg.wait_for_timeout(900); ok('Enter works on a fallback result', dlg(pg)==0)
    # ---------- every content type lands on the specific entry
    pg.goto(B+'/'); pg.wait_for_timeout(1200); op(pg); typ(pg,'skill 2'); ok('skills searchable (Skills group)', 'SKILLS' in ' '.join(headers(pg)).upper())
    pg.keyboard.press('Enter'); pg.wait_for_timeout(1500)
    ok('skill result opens /skills, entry expanded + focused, URL clean', '/skills' in pg.url and 'focus=' not in pg.url and pg.locator('button[aria-expanded=true]').count()==1 and pg.evaluate("!!document.activeElement.closest('[data-focus-id]')"), pg.url)
    op(pg); typ(pg,'club'); pg.keyboard.press('Enter'); pg.wait_for_timeout(1500)
    ok('experience result expands that entry', '/experience' in pg.url and pg.locator('li[data-focus-id=exp-3] button[aria-expanded=true]').count()==1 and pg.evaluate("!!document.activeElement.closest('[data-focus-id=exp-3]')"))
    op(pg); typ(pg,'achievement 3'); pg.keyboard.press('Enter'); pg.wait_for_timeout(1300)
    ok('achievement result scrolls to + focuses the card', '/achievements' in pg.url and pg.evaluate("!!document.activeElement.closest('[data-focus-id=ach-3]')") or pg.evaluate("document.querySelector('[data-focus-id=ach-3]')!==null"))
    op(pg); typ(pg,'article 2'); pg.keyboard.press('Enter'); pg.wait_for_timeout(1300)
    ok('blog result opens the article; focus on main content', '/blog/post-2' in pg.url and act(pg)=='main')
    op(pg); typ(pg,'cert 3'); pg.keyboard.press('Enter'); pg.wait_for_timeout(1300)
    ok('certificate result opens its preview dialog with focus inside', 'c=cert-3' in pg.url and dlg(pg)==1 and pg.evaluate("!!document.activeElement.closest('[role=dialog]')"))
    pg.keyboard.press('Escape'); pg.wait_for_timeout(600)
    op(pg); typ(pg,'project 4'); pg.keyboard.press('Enter'); pg.wait_for_timeout(1300)
    ok('project result opens detail dialog with focus inside', 'p=project-4' in pg.url and dlg(pg)==1 and pg.evaluate("!!document.activeElement.closest('[role=dialog]')"))
    # ---------- keys behind dialogs; palette over dialog
    pg.keyboard.press('g'); pg.keyboard.press('s'); pg.wait_for_timeout(600); ok('G shortcuts are ignored while a dialog is open', '/projects' in pg.url and dlg(pg)==1)
    op(pg); ok('Ctrl+K opens palette over an open dialog', dlg(pg)==2); pg.keyboard.press('Escape'); pg.wait_for_timeout(850)
    ok('Esc closes only the palette; focus back inside the dialog', dlg(pg)==1 and pg.evaluate("!!document.activeElement.closest('[role=dialog]')"))
    pg.keyboard.press('Escape'); pg.wait_for_timeout(600); ok('second Esc closes the dialog; focus lands on page', dlg(pg)==0 and act(pg)=='main')
    # ---------- commands, shortcuts help, recents
    op(pg); typ(pg,'>'); ok('">" switches to commands only', pg.get_by_text('Commands',exact=True).count()>=1 and all(g.upper() in ('ACTIONS','RECENT') for g in headers(pg)))
    typ(pg,'copy'); ok('command search finds "Copy page link"', 'Copy page link' in ' '.join(opts(pg))); pg.keyboard.press('Escape'); pg.wait_for_timeout(850)
    op(pg); typ(pg,'>short'); pg.keyboard.press('Enter'); pg.wait_for_timeout(700)
    ok('"Keyboard shortcuts" command opens help with focus inside', dlg(pg)==1 and pg.get_by_text('Go to (press G, then').count()==1 and pg.evaluate("!!document.activeElement.closest('[role=dialog]')"))
    pg.keyboard.press('Escape'); pg.wait_for_timeout(600); ok('help closes; focus not lost', dlg(pg)==0 and act(pg) not in ('BODY',''), act(pg))
    pg.goto(B+'/'); pg.wait_for_timeout(1200); pg.locator('body').click(position={'x':5,'y':300}); pg.keyboard.press('?'); pg.wait_for_timeout(600)
    ok('"?" opens shortcut help', dlg(pg)==1); pg.keyboard.press('Escape'); pg.wait_for_timeout(600)
    pg.goto(B+'/'); pg.wait_for_timeout(1200); op(pg); typ(pg,'skills'); pg.keyboard.press('Enter'); pg.wait_for_timeout(900)
    pg.goto(B+'/about'); pg.wait_for_timeout(1000); op(pg)
    ok('recent choice appears first under "Recent"', headers(pg)[0].upper()=='RECENT' and 'Skills' in opts(pg)[0], str(headers(pg)[:2])); pg.keyboard.press('Escape'); pg.wait_for_timeout(850)
    # ---------- G sequence feedback + nav consistency
    pg.goto(B+'/'); pg.wait_for_timeout(1200); pg.locator('body').click(position={'x':5,'y':300}); pg.keyboard.press('g'); pg.wait_for_timeout(200)
    ok('"G" shows a go-to hint (system state visible)', pg.get_by_text('Go to… press a page key').count()==1)
    pg.keyboard.press('p'); pg.wait_for_timeout(1300); ok('G then P navigates and focuses the new page', pg.url.endswith('/projects') and act(pg)=='main')
    pg.goto(B+'/blog/post-1'); pg.wait_for_timeout(1300)
    ok('dock "More" shows active state on a nested route (/blog/post-1)', pg.evaluate("!!document.querySelector('button[aria-label=\"More pages\"] span.bg-accent')"))
    ok('status bar names the section', pg.locator('header [aria-current=page]').inner_text()=='Blog')
    op(pg); typ(pg,'blog'); ok('palette marks Blog as Current on /blog/post-1', pg.locator('[role=option]:has-text("Current")').first.inner_text().startswith('Blog'))
    pg.keyboard.press('Escape'); pg.wait_for_timeout(850)
    # ---------- touch + reduced motion
    t=b.new_context(viewport={'width':390,'height':844},has_touch=True,is_mobile=True).new_page(); t.goto(B); t.wait_for_timeout(1500)
    t.get_by_label('Open command palette').tap(); t.wait_for_timeout(600); t.keyboard.type('skill 3'); t.wait_for_timeout(400)
    t.locator('[role=option]').first.tap(); t.wait_for_timeout(1500)
    ok('mobile: tap a result -> lands on that skill', '/skills' in t.url and t.locator('button[aria-expanded=true]').count()==1)
    r=b.new_context(viewport={'width':1280,'height':900},reduced_motion='reduce').new_page(); r.goto(B); r.wait_for_timeout(1200); r.keyboard.press('Control+k'); r.wait_for_timeout(400); r.keyboard.type('club'); r.wait_for_timeout(300); r.keyboard.press('Enter'); r.wait_for_timeout(1300)
    ok('reduced motion: deep link still expands + focuses', r.locator('li[data-focus-id=exp-3] button[aria-expanded=true]').count()==1)
    ok('no page errors', not errs, ';'.join(errs)[:200]); b.close()
